sys_aw_page.page_definition:
{
  "layout": {
    "type": "container",
    "children": [
      {
        "type": "header",
        "title": "📋 Trade Book Records",
        "subtitle": "View and manage all your trading positions",
        "actions": [
          {
            "type": "button",
            "label": "New Trade",
            "variant": "primary",
            "action": "create_record",
            "icon": "plus"
          },
          {
            "type": "button",
            "label": "Export Data",
            "variant": "secondary",
            "action": "export_list",
            "icon": "download"
          },
          {
            "type": "button",
            "label": "Refresh",
            "variant": "tertiary",
            "action": "refresh_list",
            "icon": "refresh"
          }
        ]
      },
      {
        "type": "filters",
        "title": "Filter Trades",
        "filters": [
          {
            "field": "stock_name",
            "label": "Stock Name",
            "type": "string",
            "operator": "contains"
          },
          {
            "field": "date",
            "label": "Trade Date",
            "type": "date_range",
            "operator": "between"
          },
          {
            "field": "buying_price",
            "label": "Price Range",
            "type": "number_range",
            "operator": "between"
          }
        ]
      },
      {
        "type": "list",
        "table": "x_snc_trade_mana_0_trade_book",
        "view": "default",
        "columns": [
          {
            "field": "number",
            "label": "Trade #",
            "width": "120px",
            "sortable": true
          },
          {
            "field": "stock_name",
            "label": "Stock Name",
            "width": "200px",
            "sortable": true,
            "searchable": true
          },
          {
            "field": "buying_price",
            "label": "Buying Price",
            "width": "120px",
            "sortable": true,
            "format": "currency"
          },
          {
            "field": "stop_loss",
            "label": "Stop Loss",
            "width": "120px",
            "sortable": true,
            "format": "currency"
          },
          {
            "field": "date",
            "label": "Trade Date",
            "width": "120px",
            "sortable": true,
            "format": "date"
          },
          {
            "field": "sys_created_on",
            "label": "Created",
            "width": "140px",
            "sortable": true,
            "format": "datetime"
          }
        ],
        "actions": [
          {
            "type": "row_action",
            "label": "Edit",
            "action": "edit_record",
            "icon": "edit"
          },
          {
            "type": "row_action",
            "label": "View",
            "action": "view_record",
            "icon": "eye"
          },
          {
            "type": "row_action",
            "label": "Delete",
            "action": "delete_record",
            "icon": "trash",
            "confirm": "Are you sure you want to delete this trade record?"
          }
        ],
        "pagination": {
          "page_size": 25,
          "show_page_size_options": true,
          "page_size_options": [10, 25, 50, 100]
        },
        "sorting": {
          "default_field": "date",
          "default_direction": "desc"
        }
      },
      {
        "type": "summary_cards",
        "title": "Quick Statistics",
        "cards": [
          {
            "title": "Total Trades",
            "value": "${count}",
            "icon": "trending-up",
            "color": "blue"
          },
          {
            "title": "Total Investment",
            "value": "${sum:buying_price}",
            "icon": "dollar-sign",
            "color": "green",
            "format": "currency"
          },
          {
            "title": "Average Price",
            "value": "${avg:buying_price}",
            "icon": "bar-chart",
            "color": "orange",
            "format": "currency"
          },
          {
            "title": "Risk Exposure",
            "value": "${sum:stop_loss}",
            "icon": "shield",
            "color": "red",
            "format": "currency"
          }
        ]
      }
    ]
  }
}
